package de.eldoria.bloodnight.generated;

import de.eldoria.bloodnight.api.CompiledBehaviour;
import de.eldoria.bloodnight.api.MobContext;
import org.bukkit.entity.Blaze;
import org.bukkit.event.entity.EntityTargetLivingEntityEvent;

public final class FirePhantomBehaviour implements CompiledBehaviour {
    private final MobContext context;

    public FirePhantomBehaviour(MobContext context) {
        this.context = context;
    }

    @Override
    public void onNightEnd() {
        // node #6 mob.night_end
        // node #9 flow.branch
        // node #7 mob.extension
        final Blaze extension = ((Blaze) this.context.extension());
        if (extension == null) return;
        // node #8 entity.remove
        extension.remove();
        // node #10
    }

    @Override
    public void onTargetChange(EntityTargetLivingEntityEvent event) {
        // node #18 event.target_change
        // node #21 flow.branch
        // node #19 mob.extension
        final Blaze extension = ((Blaze) this.context.extension());
        if (extension == null) return;
        // node #20 mob.mutate
        extension.setTarget(event.getTarget());
        // node #22
    }
}
